import {STORES,NAV,PRIORITIES,STATUSES,fmtNumber,dateWita,prettyDate,escapeHtml as esc,storeName} from './constants.js';
import {isDemo,isConfigured,start,login,logout,loadAll,saveIssue,verifyIssue,saveBriefing,submitBriefingBundle,saveSchedule,saveAssignment,saveChecklist,validateChecklist,saveDso,validateDso,submitVisitBundle,saveTemplate,uploadEvidence,evidenceUrl,availableStores,EXPORT_DATASETS,fetchCompleteRows,maintenanceUsage,maintenancePreview,maintenanceArchive,maintenanceHistory,maintenanceDownloadBatch,maintenancePurge} from './data.js';

const $=id=>document.getElementById(id), mgr=()=>['master','spv'].includes(state.profile?.role),master=()=>state.profile?.role==='master';
const state={page:'overview',profile:null,data:null,date:dateWita(),store:'all',brand:'all',subTab:'ringkasan',status:'all',search:'',busy:false,modal:null,editing:null,sidebar:false,error:null,visitIssues:1,visitPointEdit:{},checkMode:'hari',dsoForm:'OPENING',scheduleView:'week',weekOffset:0,photoPreview:null,range:'30',maintenance:{usage:null,history:[],selection:null,preview:null,downloaded:{},message:''}};
const ICON={overview:'◫',compliance:'◉',issues:'▤',checklist:'☑',dso:'▣',schedule:'▦',visits:'⌖',pending:'⚑',scorecard:'◴',assignments:'✦',settings:'⚙',maintenance:'▥'};
const TASK_STATUS=['Open','On Progress','Pending','Selesai','Dibatalkan'];
const isOpen=r=>!['Selesai','Dibatalkan'].includes(r.status), late=r=>isOpen(r)&&r.due_date&&r.due_date<state.date;
const scopeStores=()=>availableStores(state.profile||{role:'master'}).filter(s=>(state.store==='all'||state.store===s.id)&&(state.brand==='all'||state.brand===s.brand));
const scoped=arr=>(arr||[]).filter(x=>scopeStores().some(s=>s.id===x.store_id));
const showStore=id=>esc(storeName(id));
const issues=()=>scoped(state.data?.issues),pending=()=>issues().filter(x=>x.origin==='visit'&&isOpen(x));
const briefings=()=>scoped(state.data?.briefings),dayBriefings=()=>briefings().filter(b=>b.briefing_date===state.date);
const briefingStores=()=>new Set(dayBriefings().map(b=>b.store_id));
const withDate=(date,shift)=>{const d=new Date(`${date}T12:00:00+08:00`);d.setUTCDate(d.getUTCDate()+shift);return dateWita(d);};
const badge=(v,cls='')=>`<span class="pill ${cls}">${esc(v||'—')}</span>`;
const priority=v=>badge(v,v==='Kritis'?'critical':v==='Tinggi'?'high':'');
const status=v=>badge(v,v==='Selesai'||v==='Approved'?'done':v==='Pending'||v==='Rejected'?'pending':v==='Open'?'overdue':'');
const opt=(v,label,sel)=>`<option value="${esc(v)}" ${v===sel?'selected':''}>${esc(label||v)}</option>`;
const selectStore=(value='all',all=true)=>`${all?opt('all','Semua toko',value):''}${scopeStores().map(s=>opt(s.id,s.name,value)).join('')}`;
function toast(message,failed=false){document.querySelector('.toast')?.remove();const d=document.createElement('div');d.className='toast'+(failed?' error':'');d.textContent=message;document.body.appendChild(d);setTimeout(()=>d.remove(),4500);}
function head(title,subtitle,actions=''){return `<div class="page-head"><div><div class="eyebrow">COMMERCIAL OPERATIONS / ${esc(state.page.toUpperCase())}</div><h2 class="page-title">${title}</h2><p class="page-subtitle">${subtitle}</p></div><div class="page-actions">${actions}</div></div>`;}
function filterbar(date=true){return `<div class="filters">${date?`<div class="field"><label>Tanggal pantau (WITA)</label><input id="monitorDate" type="date" value="${state.date}"></div>`:''}<div class="field"><label>Toko</label><select id="storeFilter">${selectStore(state.store)}</select></div><div class="field"><label>Brand</label><select id="brandFilter">${opt('all','Semua brand',state.brand)}${opt('MAMU','MAMU',state.brand)}${opt('Tigalapankaos','Tigalapankaos',state.brand)}</select></div><button class="btn primary" data-action="apply">Terapkan</button></div>`;}
function metric(label,value,foot,icon='',type='',page=''){return `<div class="metric ${type}" ${page?`data-page="${page}" role="button" tabindex="0"`:''}><div class="metric-head"><span class="metric-label">${label}</span><span class="metric-icon">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-footer">${foot}</div></div>`;}
function panel(title,sub,content,action=''){return `<section class="panel"><div class="panel-head"><div class="panel-heading"><h3 class="panel-title">${title}</h3><p class="panel-desc">${sub}</p></div>${action}</div>${content}</section>`;}
const empty=(s='Belum ada data.')=>`<div class="empty">${esc(s)}</div>`;
const short=s=>s.replace('TIGALAPANKAOS','TK').replace('MAMU ','M. ');
function sortedIssueList(list){return [...list].sort((a,b)=>Number(late(b))-Number(late(a))||(PRIORITIES.indexOf(a.priority)-PRIORITIES.indexOf(b.priority))||String(a.due_date||'9999').localeCompare(String(b.due_date||'9999')));}
function issueRows(list,compact=false){
 const a=sortedIssueList(list.filter(x=>(state.status==='all'||x.status===state.status)&&(!state.search||[x.title,x.pic_name,storeName(x.store_id)].join(' ').toLowerCase().includes(state.search.toLowerCase()))));
 return panel(compact?'Prioritas tindak lanjut':'Daftar issue dan action plan',`${a.length} temuan sesuai filter`,`<div class="table-wrap"><table class="data-table"><thead><tr><th>Masalah</th><th>Toko</th><th>Prioritas</th><th>PIC</th><th>Due Date</th><th>Status</th><th>Progres</th><th>Validasi</th><th>Aksi</th></tr></thead><tbody>${a.map(x=>`<tr><td><div class="table-title" title="${esc(x.title)}">${esc(x.title)}</div><small class="mild">${esc(x.category||'—')} · ${esc(x.origin)}</small></td><td>${showStore(x.store_id)}</td><td>${priority(x.priority)}</td><td>${esc(x.pic_name||'Belum diisi')}</td><td class="${late(x)?'text-red':''}">${prettyDate(x.due_date)}</td><td>${status(x.status)}</td><td><div class="progress"><i style="width:${Math.min(100,Math.max(0,Number(x.progress)||0))}%"></i></div><small>${Number(x.progress)||0}%</small></td><td>${x.verified_at?badge('Approved','done'):x.status==='Selesai'?badge('Butuh validasi','pending'):badge('—')}</td><td class="actions-cell"><button class="btn small" data-edit-issue="${esc(x.id)}">Detail / Edit</button></td></tr>`).join('')||'<tr><td colspan="9">'+empty('Tidak ada temuan sesuai filter')+'</td></tr>'}</tbody></table></div>`,`<button class="btn small" data-action="export">↓ CSV</button>`);
}
function compliancePanel(){const seen=briefingStores(),stores=scopeStores();return panel('Kepatuhan input briefing',`Tanggal ${prettyDate(state.date)} • NIHIL tetap dihitung sudah update`,`<div class="matrix">${stores.map(s=>{const entries=dayBriefings().filter(b=>b.store_id===s.id),isDone=seen.has(s.id);return `<div class="matrix-card"><div><b>${showStore(s.id)}</b><small>${esc(s.region)} · ${entries.length?entries.every(b=>b.no_findings)?'NIHIL':'Sesi: '+entries.map(e=>e.shift).join(', '):'Belum ada input'}</small></div>${badge(isDone?'SUDAH UPDATE':'BELUM UPDATE',isDone?'done':'overdue')}</div>`;}).join('')}</div>`,`<button class="btn small primary" data-action="open-briefing">＋ Briefing</button>`);}
function scorePanel(){const stores=scopeStores();const body=stores.map(s=>{const arr=issues().filter(i=>i.store_id===s.id),closed=arr.filter(i=>i.status==='Selesai').length,over=arr.filter(late).length,vis=scoped(state.data.visits).filter(v=>v.store_id===s.id),score=vis.filter(v=>v.score!=null).sort((a,b)=>String(b.visit_date).localeCompare(String(a.visit_date)))[0]?.score;return `<tr><td>${showStore(s.id)}</td><td>${arr.length}</td><td>${arr.filter(isOpen).length}</td><td class="${over?'text-red':''}">${over}</td><td>${arr.length?Math.round(100*closed/arr.length)+'%':'—'}</td><td>${score!=null?Number(score).toFixed(0)+'%':'—'}</td><td>${briefingStores().has(s.id)?badge('Sudah','done'):badge('Belum','overdue')}</td></tr>`;}).join('');return panel('Scorecard 12 Toko','Perbandingan kinerja dan status input harian',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Toko</th><th>Total issue</th><th>Open</th><th>Overdue</th><th>Closed %</th><th>Skor visit terakhir</th><th>Briefing</th></tr></thead><tbody>${body}</tbody></table></div>`);}
function visitPanel(){const visits=scoped(state.data.visits),iss=issues().filter(i=>i.origin==='visit');return `<div class="grid-kpis">${metric('Visit tercatat',visits.length,'Histori semua visit','⌖')}${metric('Issue dari visit',iss.length,'Semua hasil temuan','▤')}${metric('Pending Matter',iss.filter(isOpen).length,'Belum dituntaskan','⚑')}${metric('Masalah visit overdue',iss.filter(late).length,'Perlu eskalasi','!','danger')}</div>${visitTable(visits)}`;}
function visitTable(list){return panel('Riwayat visiting check point','Klik Lihat untuk foto per checkpoint dan seluruh issue',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Tanggal</th><th>Toko</th><th>Evaluator</th><th>Nilai</th><th>Issue terkait</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${[...list].sort((a,b)=>String(b.visit_date).localeCompare(String(a.visit_date))).map(x=>`<tr><td>${prettyDate(x.visit_date)}</td><td>${showStore(x.store_id)}</td><td>${esc(x.evaluator_name)}</td><td>${x.score!=null?Number(x.score).toFixed(1)+'%':'—'}</td><td>${issues().filter(i=>i.visit_id===x.id).length}</td><td>${status(x.status)}</td><td><button class="btn small" data-detail-visit="${esc(x.id)}">Lihat</button></td></tr>`).join('')||'<tr><td colspan="7">'+empty()+'</td></tr>'}</tbody></table></div>`);}
function overview(){
 const all=issues(),open=all.filter(isOpen),overdue=open.filter(late),done=all.filter(i=>i.status==='Selesai'),stores=scopeStores(),reported=briefingStores(),covered=stores.filter(s=>reported.has(s.id)).length,percent=stores.length?Math.round(covered/stores.length*100):0,urgent=sortedIssueList(open).slice(0,6);
 const tabs=[['ringkasan','Overview'],['kepatuhan','Kepatuhan'],['action','Action Plan'],['visit','Visit & Issue'],['score','Scorecard']];let body='';
 if(state.subTab==='ringkasan'){
  const p=urgent.map(i=>`<div class="issue-row"><i class="issue-left-bar"></i><div class="issue-detail"><h4 title="${esc(i.title)}">${esc(i.title)}</h4><p>${showStore(i.store_id)} · ${esc(i.pic_name||'PIC belum ada')} · ${prettyDate(i.due_date)}</p></div>${priority(i.priority)}</div>`).join('')||empty('Tidak ada masalah terbuka');
  const report=stores.map(s=>`<div class="store-row"><div><span class="store-name">${showStore(s.id)}</span><span class="store-meta"> · ${esc(s.region)}</span></div><span class="status-icon ${reported.has(s.id)?'':'miss'}">${reported.has(s.id)?'✓':'×'}</span></div>`).join('');
  const trend=Array.from({length:7},(_,i)=>{const date=withDate(state.date,i-6);return {date,n:briefings().filter(b=>b.briefing_date===date).length,done:all.filter(a=>a.closed_at?.startsWith(date)).length}});const max=Math.max(1,...trend.map(x=>x.n),...trend.map(x=>x.done));
  body=`<div class="section-grid">${panel('Masalah prioritas hari ini','Overdue, urgensi dan PIC',`<div class="panel-body">${p}</div>`,`<button class="btn small" data-page="issues">Semua issue →</button>`)}${panel('Kepatuhan briefing 12 toko',`Tanggal ${prettyDate(state.date)}`,`<div class="panel-body">${report}</div>`,`<button class="btn small" data-page="compliance">Detail →</button>`)}</div><div class="section-grid even">${panel('Tren 7 hari','Briefing masuk dan masalah selesai',`<div class="panel-body"><div class="trend">${trend.map(x=>`<div class="trend-col"><div class="trend-bars"><i class="trend-bar" style="height:${Math.max(2,x.n/max*130)}px"></i><i class="trend-bar light" style="height:${Math.max(2,x.done/max*130)}px"></i></div><span class="trend-label">${x.date.slice(8)}/${x.date.slice(5,7)}</span></div>`).join('')}</div><div class="legend"><span><i></i>Briefing</span><span><i class="light"></i>Issue selesai</span></div></div>`)}${panel('Keputusan hari ini','Rekomendasi berdasarkan indikator aktual',`<div class="panel-body"><div class="activity-list"><div class="activity-item"><span class="symbol">⏱</span><div><b>${overdue.length} issue overdue</b><p>Konfirmasi ulang target dan eskalasi PIC</p></div></div><div class="activity-item"><span class="symbol">✎</span><div><b>${open.filter(i=>!i.due_date||!i.pic_name).length} issue tanpa PIC / deadline</b><p>Lengkapi action plan hari ini</p></div></div><div class="activity-item"><span class="symbol">⚑</span><div><b>${pending().length} pending matter visit</b><p>Periksa foto dan bukti penyelesaian</p></div></div></div></div>`)}</div>`;
 }else if(state.subTab==='kepatuhan')body=compliancePanel();else if(state.subTab==='action')body=issueRows(all,true);else if(state.subTab==='visit')body=visitPanel();else body=scorePanel();
 return head('Executive Control Center','Pemantauan operasional terpusat untuk 12 store',`<button class="btn outline" data-action="export">↓ CSV</button><button class="btn primary" data-action="open-briefing">＋ Briefing</button>`)
  +`<div class="demo-banner"><span><b>${isDemo?'DATA SIMULASI':'DATA SUPABASE'}</b> ${isDemo?'Hanya untuk uji coba UI; bukan data produksi.':'Seluruh modul terhubung ke PostgreSQL Supabase.'}</span><span>Zona waktu Asia/Makassar · WITA</span></div>`
  +`<div class="hero"><div class="hero-content"><p class="overline">PT TIGALAPAN SUKSES INDONESIA</p><h2>Every store. One control center.</h2><p>Keputusan lebih cepat, tindakan terukur, dan bukti penyelesaian yang dapat diverifikasi.</p></div><div class="hero-side"><div class="radial" style="--pct:${percent}%"><div class="radial-inner"><div><strong>${percent}%</strong><small>Cakupan briefing</small></div></div></div><div class="hero-stat"><small>${prettyDate(state.date)}</small><b>${covered}/${stores.length} toko</b><hr><small>${stores.length-covered} toko belum update</small></div></div></div>`
  +filterbar()+`<div class="tabs">${tabs.map(([id,n])=>`<button class="tab ${state.subTab===id?'active':''}" data-subtab="${id}">${n}</button>`).join('')}</div>`
  +`<div class="grid-kpis">${metric('Briefing update',`${covered}/${stores.length}`,`${percent}% dari toko aktif`,'📣','good','compliance')}${metric('Action terbuka',fmtNumber(open.length),'Belum close','▤','','issues')}${metric('Overdue',fmtNumber(overdue.length),'Melewati tenggat','◷','danger','issues')}${metric('Pending Matter',fmtNumber(pending().length),'Temuan visit','⚑','','pending')}</div>`+body;
}
function pageIssues(pend=false){const list=issues().filter(i=>!pend||i.origin==='visit');return head(pend?'Pending Matter':'Action Plan & Issue',pend?'Hasil visiting; semua status dapat difilter dan diverifikasi.':'Masalah harian, akar penyebab, solusi, PIC, due date, serta bukti.',`<button class="btn outline" data-action="export">↓ CSV</button><button class="btn primary" data-action="open-issue">＋ Issue</button>`)+`<div class="grid-kpis">${metric('Total',list.length,'Seluruh issue','▤')}${metric('Belum selesai',list.filter(isOpen).length,'Perlu tindak lanjut','◷')}${metric('Overdue',list.filter(late).length,'Eskalasi','⚑','danger')}${metric('Tuntas',list.filter(i=>i.status==='Selesai').length,'Status selesai','✓','good')}</div>`+`<div class="toolbar"><div class="field wide"><label>Cari</label><input id="issueSearch" value="${esc(state.search)}" placeholder="Masalah, nama toko, PIC"></div><div class="field"><label>Status</label><select id="issueStatus">${opt('all','Semua status',state.status)}${STATUSES.map(s=>opt(s,s,state.status)).join('')}</select></div><div class="field"><label>Toko</label><select id="storeFilter">${selectStore(state.store)}</select></div><button class="btn primary" data-action="apply-issues">Terapkan</button></div>`+issueRows(list);}
function pageCompliance(){const seen=briefingStores(),s=scopeStores();return head('Kepatuhan 12 Store','Pantau tanggal briefing dan histori per toko',`<button class="btn outline" data-action="export">↓ CSV</button><button class="btn primary" data-action="open-briefing">＋ Briefing</button>`)+filterbar()+`<div class="grid-kpis">${metric('Sudah update',s.filter(x=>seen.has(x.id)).length,'Briefing tercatat','✓','good')}${metric('Belum update',s.filter(x=>!seen.has(x.id)).length,'Perlu follow-up','!','danger')}${metric('NIHIL',dayBriefings().filter(x=>x.no_findings).length,'Tidak ada temuan','—')}${metric('Sesi briefing',dayBriefings().length,'Semua shift','◷')}</div>`+compliancePanel();}
function pageChecklist(){const scope=scopeStores(),dt=state.date,tpl=(state.data.checklist_templates||[]).filter(t=>t.active&&(t.store_id===null||scope.some(s=>s.id===t.store_id)));const completed=scoped(state.data.checklists).filter(x=>x.check_date===dt);const cards=[];
 for(const st of scope){const local=tpl.filter(t=>!t.store_id||t.store_id===st.id),p=completed.filter(x=>x.store_id===st.id);for(const t of local){const r=p.find(x=>x.template_id===t.id);cards.push({store:st,template:t,entry:r});}}
 const done=cards.filter(x=>x.entry?.status==='Selesai').length;
 return head('Assignment Checklist Store','Tugas harian dari template, catatan, foto dan validasi SPV',`<button class="btn outline" data-action="export">↓ CSV</button>${master()?'<button class="btn" data-action="open-check-template">＋ Template</button>':''}`)+filterbar()+`<div class="grid-kpis">${metric('Total assignment',cards.length,'Tanggal dipilih','☑')}${metric('Selesai',done,'Telah dicentang','✓','good')}${metric('Belum selesai',cards.length-done,'Perlu dikerjakan','!','danger')}${metric('Tervalidasi',cards.filter(x=>x.entry?.validated_at).length,'Oleh SPV','◉')}</div>`+panel('Tugas Store',`Tanggal ${prettyDate(dt)} • status menyesuaikan toko aktif`,`<div class="checkpoint-list">${cards.map(({store,template,entry})=>`<div class="checkpoint-item"><div class="checkpoint-check ${entry?.status==='Selesai'?'checked':''}" data-check-entry="${esc(entry?.id||'')}" data-check-template="${esc(template.id)}" data-check-store="${store.id}">${entry?.status==='Selesai'?'✓':'○'}</div><div class="checkpoint-info"><b>${esc(template.title)}</b><small>${showStore(store.id)} · ${esc(template.category||'Operasional')} ${entry?.validated_at?' · Validasi SPV':''}</small>${entry?.note?`<p>${esc(entry.note)}</p>`:''}</div><div class="checkpoint-actions"><button class="btn small" data-check-detail="${esc(entry?.id||'')}" data-check-template="${esc(template.id)}" data-check-store="${store.id}">Isi / Foto</button>${mgr()&&entry?.status==='Selesai'&&!entry?.validated_at?`<button class="btn small primary" data-check-validate="${esc(entry.id)}">Validasi</button>`:''}</div></div>`).join('')||empty('Belum ada template assignment. Master dapat membuat template.')}</div>`);
}
function pageDso(){const dt=state.date,s=scopeStores(),forms=['OPENING','DURING','CLOSING','LAMPU'];const data=scoped(state.data.dso).filter(x=>x.report_date===dt);return head('Daily Store Operation','Laporan Opening, During, Closing, Lampu — foto dan validasi',`<button class="btn outline" data-action="export">↓ CSV</button>`)+filterbar()+`<div class="grid-kpis">${metric('Form dikirim',data.length,`Target ${s.length*forms.length} form`,'▣')}${metric('Approved',data.filter(x=>x.status==='Approved').length,'Validasi manajemen','✓','good')}${metric('Menunggu validasi',data.filter(x=>x.status==='Submitted').length,'Belum ditinjau','◷')}${metric('Rejected',data.filter(x=>x.status==='Rejected').length,'Perlu revisi','!','danger')}</div>`+panel('Matriks Daily Store Operation',`Tanggal ${prettyDate(dt)} • setiap sel bisa dibuka untuk form atau detail`,`<div class="table-wrap"><table class="data-table"><thead><tr><th>Toko</th>${forms.map(f=>`<th>${f}</th>`).join('')}</tr></thead><tbody>${s.map(st=>`<tr><td><b>${showStore(st.id)}</b></td>${forms.map(f=>{const r=data.find(x=>x.store_id===st.id&&x.form_code===f);return `<td><button class="btn small ${r?.status==='Approved'?'':'outline'}" data-dso-store="${st.id}" data-dso-form="${f}">${r?esc(r.status):'Belum input'}</button></td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`);
}
function pageSchedule(){const arr=scoped(state.data.schedules).filter(x=>state.scheduleView==='all'||x.visit_date>=state.date&&x.visit_date<=withDate(state.date,6));const groups=new Map();for(const r of arr){if(!groups.has(r.visit_date))groups.set(r.visit_date,[]);groups.get(r.visit_date).push(r);}
 return head('Jadwal Visit','Agenda toko, PIC, waktu WITA, serta kontrol penyelesaian',`<button class="btn outline" data-action="export">↓ CSV</button>${mgr()?'<button class="btn primary" data-action="open-schedule">＋ Jadwal</button>':''}`)+filterbar()+`<div class="toolbar"><div class="segmented">${[['week','7 Hari'],['all','Semua Jadwal']].map(([id,label])=>`<button class="seg-button ${state.scheduleView===id?'active':''}" data-schedule-view="${id}">${label}</button>`).join('')}</div></div>`+`<div class="grid-kpis">${metric('Total agenda',arr.length,'Jadwal dalam filter','▦')}${metric('Akan datang',arr.filter(x=>x.status==='Rencana'&&x.visit_date>=state.date).length,'Belum visit','◷')}${metric('Selesai',arr.filter(x=>x.status==='Selesai').length,'Terlaksana','✓','good')}${metric('Batal',arr.filter(x=>x.status==='Batal').length,'Tidak terlaksana','×','danger')}</div>`+panel('Timeline jadwal visit','Klik agenda untuk edit jadwal dan status',`<div class="schedule-list">${[...groups].sort((a,b)=>a[0].localeCompare(b[0])).map(([day,list])=>`<div class="schedule-day"><div class="schedule-date"><b>${prettyDate(day)}</b><small>${list.length} visit</small></div><div class="schedule-entries">${list.map(x=>`<button class="schedule-entry" data-edit-schedule="${esc(x.id)}"><div><b>${esc(x.start_time?.slice(0,5)||'—')}–${esc(x.end_time?.slice(0,5)||'—')} WITA</b><small>${showStore(x.store_id)}</small></div><div class="schedule-agenda">${esc(x.agenda)}</div>${status(x.status)}</button>`).join('')}</div></div>`).join('')||empty('Belum ada jadwal di rentang ini')}</div>`);
}
function pageVisits(){const arr=scoped(state.data.visits);return head('Visiting Check Point','Audit toko menggunakan checklist 15 point, foto, dan issue terintegrasi',`<button class="btn outline" data-action="export">↓ CSV</button>${mgr()?'<button class="btn primary" data-action="open-visit">＋ Visit Baru</button>':''}`)+filterbar()+visitPanel()+`<div class="notice">Seluruh checkpoint Tidak Sesuai wajib dilengkapi issue, PIC dan due date saat submit. Issue langsung masuk Pending Matter.</div>`;}
function pageScore(){return head('Scorecard Store','Monitor hasil kerja dan tindak lanjut setiap cabang',`<button class="btn outline" data-action="export">↓ CSV</button>`)+filterbar()+scorePanel();}
function pageAssignments(){const arr=scoped(state.data.assignments);return head('Daily Task & Assignment','Penugasan Store/SPV dengan PIC, due date, prioritas, dan progres',`<button class="btn outline" data-action="export">↓ CSV</button><button class="btn primary" data-action="open-assignment">＋ Assignment</button>`)+filterbar()+panel('Penugasan',`${arr.filter(isOpen).length} belum selesai`,`<div class="table-wrap"><table class="data-table"><thead><tr><th>Tugas</th><th>Toko</th><th>PIC</th><th>Due Date</th><th>Prioritas</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${arr.map(a=>`<tr><td>${esc(a.title)}</td><td>${showStore(a.store_id)}</td><td>${esc(a.pic_name)}</td><td class="${late(a)?'text-red':''}">${prettyDate(a.due_date)}</td><td>${priority(a.priority)}</td><td>${status(a.status)}</td><td><button class="btn small" data-edit-assignment="${esc(a.id)}">Edit</button></td></tr>`).join('')||'<tr><td colspan="7">'+empty()+'</td></tr>'}</tbody></table></div>`);}
const MB=n=>((Number(n)||0)/1024/1024).toFixed(2)+' MB';
const CLEANUP_TABLES=[['issues','Issue tervalidasi'],['checklist_entries','Checklist tervalidasi'],['dso_reports','DSO approved'],['visit_schedules','Jadwal selesai/batal'],['assignments','Assignment selesai 100%']];
const exportStoreOptions=()=>`${opt('all','Semua toko','all')}${availableStores(state.profile).map(s=>opt(s.id,s.name,'all')).join('')}`;
function pageMaintenance(){
 if(!master())return head('Akses ditolak','Menu ini khusus Master.');
 const m=state.maintenance,usage=m.usage||{},r=usage.rows||{};
 const kpis=`<div class="grid-kpis">${metric('Masalah aktif',fmtNumber(r.issues),'Semua status','▤')}${metric('Checklist aktif',fmtNumber(r.checklists),'Tervalidasi & berjalan','☑')}${metric('Arsip database',fmtNumber(r.archive_rows),'Masih memakai ruang DB','▣')}${metric('Foto tersimpan',MB(usage.photo_bytes),'Storage privat','◉')}</div>`;
 const options=Object.entries(EXPORT_DATASETS).map(([id,item])=>opt(id,item.table,id==='issues'?'issues':'')).join('');
 const history=m.history.map(b=>`<tr><td>${esc(b.source_table)}</td><td>${esc(b.store_id||'Semua toko')}</td><td>${prettyDate(b.cutoff_date)}</td><td>${fmtNumber(b.row_count)}</td><td>${status(b.status==='archived'?'Tersimpan':'Dihapus')}</td><td><small title="${esc(b.sha256||'')}">${esc((b.sha256||'').slice(0,12))}…</small></td><td class="actions-cell">${b.status==='archived'?`<button class="btn small" data-action="download-archive" data-batch="${esc(b.batch_id)}">↓ Backup JSONL</button>${m.downloaded[b.batch_id]?`<button class="btn small danger" data-action="purge-archive" data-batch="${esc(b.batch_id)}">Hapus arsip</button>`:''}`:'—'}</td></tr>`).join('')||'<tr><td colspan="7">Belum ada histori arsip.</td></tr>';
 return head('Export, Backup & Manajemen Database','Kontrol penggunaan penyimpanan tanpa menghapus data operasional yang masih aktif.',`<button class="btn outline" data-action="reload-maintenance">↻ Muat ulang</button>`)+kpis+
 `<div class="notice"><b>Perlindungan data:</b> hanya Master boleh arsip atau hapus. Masalah belum selesai, visit, briefing, master data dan foto yang direferensikan tidak akan dihapus oleh mekanisme ini. Arsip masih menggunakan kapasitas DB sampai dibackup dan dipurge. <b>File JSONL/CSV hanya menyimpan alamat/path foto, bukan foto aslinya.</b></div>`+
 `<div class="section-grid even">`+
 panel('Export CSV lengkap','Seluruh baris yang dapat diakses, tidak dibatasi jumlah baris yang tampil di dashboard.',`<div class="panel-body" style="display:grid;gap:13px"><div class="field"><label>Pilih menu/dataset</label><select id="exportDataset">${options}</select></div><div class="field"><label>Toko</label><select id="exportStore">${exportStoreOptions()}</select></div><div class="form-grid"><div class="field"><label>Dari tanggal (opsional)</label><input type="date" id="exportFrom"></div><div class="field"><label>Sampai tanggal (opsional)</label><input type="date" id="exportTo"></div></div><p class="mild">JSON pada form (jawaban, konfigurasi) tetap masuk CSV dalam bentuk teks. ID lama dan foto path dipertahankan.</p><button class="btn primary" data-action="export-dataset">↓ Export CSV semua halaman</button><button class="btn" data-action="backup-all">↓ Backup seluruh dataset (JSONL)</button></div>`)+
 panel('Arsip data selesai','Minimum usia 90 hari, harus selesai/tervalidasi sesuai jenis data.',`<div class="panel-body" style="display:grid;gap:13px"><div class="field"><label>Jenis data yang boleh diarsip</label><select id="archiveTable">${CLEANUP_TABLES.map(([id,label])=>opt(id,label,m.selection?.table||'issues')).join('')}</select></div><div class="field"><label>Toko</label><select id="archiveStore">${opt('all','Semua toko',m.selection?.store||'all')}${availableStores(state.profile).map(st=>opt(st.id,st.name,m.selection?.store||'all')).join('')}</select></div><div class="field"><label>Arsip data sebelum tanggal</label><input id="archiveCutoff" type="date" value="${esc(m.selection?.cutoff||withDate(dateWita(),-180))}"></div><button class="btn" data-action="preview-maintenance">Preview data yang aman diarsip</button>${m.preview?`<div class="notice"><b>${fmtNumber(m.preview.eligible)} baris</b> memenuhi syarat. ${m.preview.eligible>2000?'Perkecil periode atau pilih satu toko.':'Data aktif dan belum tervalidasi tidak termasuk.'}</div><div class="field"><label>Ketik ARSIP DATA SELESAI</label><input id="archivePhrase" autocomplete="off" placeholder="ARSIP DATA SELESAI"></div><button class="btn danger" data-action="archive-maintenance" ${m.preview.eligible<1||m.preview.eligible>2000?'disabled':''}>Arsip sesuai preview</button>`:''}</div>`)+
 `</div>`+
 panel('Histori arsip & penghapusan permanen','Unduh dan verifikasi SHA256 dahulu. Penghapusan permanen hanya berlaku untuk SALINAN arsip sesudah 24 jam.',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Dataset</th><th>Toko</th><th>Sebelum</th><th>Baris</th><th>Status</th><th>SHA256</th><th>Aksi</th></tr></thead><tbody>${history}</tbody></table></div>`)+
 `<div class="notice"><b>Pengelolaan foto:</b> foto otomatis dikompres sebagai WebP ketika diunggah. Pembersihan file foto tidak dilakukan otomatis agar tidak menghilangkan bukti yang masih dipakai. Lakukan audit referensi dan backup foto terpisah sebelum menghapus objek Storage.</div>`;
}
async function loadMaintenance(){if(!master())throw new Error('Khusus Master.');const [usage,history]=await Promise.all([maintenanceUsage(),maintenanceHistory()]);state.maintenance.usage=usage;state.maintenance.history=history;render();}
function downloadText(file,content,type='text/plain;charset=utf-8'){const blob=typeof content==='string'?new Blob([content],{type}):content;const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=file;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),20000);}
async function exportDatasetNow(dataset,filters={}){
 let count=0;toast('Membaca semua halaman data dari Supabase…');
 const records=await fetchCompleteRows(dataset,filters,n=>{count=n;});
 if(!records.length){toast('Dataset tidak memiliki data sesuai filter.',true);return;}
 CSV(records,`tigalapan_${dataset}_${dateWita()}_${records.length}rows.csv`);
 toast(`CSV ${dataset}: ${fmtNumber(count)} baris disiapkan, bukan hanya data yang terlihat di layar.`);
}
async function backupAllDatasets(){if(!master())throw new Error('Hanya Master dapat membuat backup semua dataset.');
 const lines=[JSON.stringify({type:'BACKUP_MANIFEST',application:'Tigalapan Assignment',at:new Date().toISOString(),photo_binaries_included:false,notice:'Foto wajib dibackup terpisah dari Supabase Storage'})];
 for(const dataset of Object.keys(EXPORT_DATASETS)){
  const rows=await fetchCompleteRows(dataset,{},()=>{});
  for(const row of rows){if(dataset==='settings'&&/secret|token|password|api.?key|private.?key/i.test(row.key||''))continue;lines.push(JSON.stringify({table:EXPORT_DATASETS[dataset].table,row}));}
 }
 const output=lines.join('\n');
 if('CompressionStream' in window){const compressed=await new Response(new Blob([output]).stream().pipeThrough(new CompressionStream('gzip'))).blob();downloadText(`tigalapan_backup_${dateWita()}.jsonl.gz`,compressed,'application/gzip');}
 else downloadText(`tigalapan_backup_${dateWita()}.jsonl`,output,'application/x-ndjson;charset=utf-8');
 toast('Backup data & konfigurasi diunduh. Backup binary foto tetap harus terpisah.');
}
async function previewMaintenance(){const table=$('archiveTable')?.value,store=$('archiveStore')?.value,cutoff=$('archiveCutoff')?.value;const result=await maintenancePreview(table,cutoff,store);state.maintenance.selection={table,store,cutoff};state.maintenance.preview=result;render();}
async function archiveMaintenance(){const {table,store,cutoff}=state.maintenance.selection||{},p=state.maintenance.preview;const phrase=$('archivePhrase')?.value||'';
 if(phrase!=='ARSIP DATA SELESAI')throw new Error('Tulis kalimat konfirmasi arsip dengan tepat.');
 if(!p||p.eligible<1)throw new Error('Jalankan preview terlebih dahulu.');
 if(!window.confirm(`${p.eligible} baris selesai akan dipindahkan dari data aktif ke arsip database. Lanjutkan?`))return;
 const result=await maintenanceArchive(table,cutoff,store,p.eligible,phrase);
 state.maintenance.preview=null;await refresh();await loadMaintenance();toast(`Berhasil mengarsipkan ${result.archived} baris. Arsip masih aman di database.`);
}
async function downloadArchiveRecord(id){const history=state.maintenance.history.find(x=>x.batch_id===id);if(!history||history.status!=='archived')throw new Error('Arsip tidak ditemukan');
 const data=await maintenanceDownloadBatch(id),digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(data));
 const sha=[...new Uint8Array(digest)].map(n=>n.toString(16).padStart(2,'0')).join('');
 if(sha!==history.sha256)throw new Error('SHA256 arsip tidak sesuai. File tidak disimpan; jangan hapus!');
 downloadText(`Tigalapan_Archive_${history.source_table}_${id}.jsonl`,data,'application/x-ndjson;charset=utf-8');
 state.maintenance.downloaded[id]=sha;render();toast('SHA256 cocok. Simpan file di penyimpanan eksternal sebelum menghapus arsip.');
}
async function purgeArchiveRecord(id){const record=state.maintenance.history.find(x=>x.batch_id===id),sha=state.maintenance.downloaded[id];
 if(!sha||!record||sha!==record.sha256)throw new Error('Unduh dan verifikasi backup JSONL terlebih dahulu.');
 const phrase=window.prompt('HANYA SETELAH file backup disimpan di tempat lain. Ketik HAPUS ARSIP PERMANEN untuk melanjutkan:');
 if(phrase!=='HAPUS ARSIP PERMANEN')return;
 if(!window.confirm('TINDAKAN PERMANEN: salinan arsip dalam database akan dihapus, tidak bisa dipulihkan tanpa file JSONL. Lanjutkan?'))return;
 const result=await maintenancePurge(id,sha,phrase);delete state.maintenance.downloaded[id];await loadMaintenance();toast(`${result.purged} baris arsip dihapus permanen. Backup eksternal harus disimpan.`);
}
function pageSettings(){return head('Master Data & Pengaturan','Template checklist, point visit dan form laporan operasional',`<button class="btn outline" data-action="export">↓ CSV</button>`)+`<div class="notice">${master()?'Anda dapat membuat dan mengubah template.':'Perubahan master data hanya dapat dilakukan oleh Master.'} Seluruh foto disimpan private di Supabase Storage, bukan Google Drive.</div>`+`<div class="section-grid even">${panel('Checkpoint visit',`${state.data.visit_templates.length} point pemeriksaan`,`<div class="panel-body">${state.data.visit_templates.map(x=>`<div class="store-row"><div><b>${esc(x.point_code)} · ${esc(x.item_title)}</b><small>${esc(x.section)}</small></div></div>`).join('')}</div>`,master()?'<button class="btn small primary" data-action="open-visit-template">＋ Point</button>':'')}${panel('Template Assignment',`${state.data.checklist_templates.length} tugas berulang`,`<div class="panel-body">${state.data.checklist_templates.map(x=>`<div class="store-row"><div><b>${esc(x.title)}</b><small>${esc(x.category||'Harian')} · ${x.store_id?showStore(x.store_id):'Semua toko'}</small></div></div>`).join('')||empty()}</div>`,master()?'<button class="btn small primary" data-action="open-check-template">＋ Template</button>':'')}</div>`+panel('Definisi form DSO',`${state.data.dso_points.length} point foto`,`<div class="panel-body">${state.data.dso_points.map(x=>`<div class="store-row"><div><b>${esc(x.form_code)} · ${esc(x.label)}</b><small>${esc(x.point_code)} ${x.required?'· Wajib':''}</small></div></div>`).join('')}</div>`,master()?'<button class="btn small primary" data-action="open-dso-template">＋ Point</button>':'');}

function field(name,label,html,wide=false){return `<div class="field ${wide?'form-full':''}"><label>${label}</label>${html}</div>`;}
const fInput=(name,value='',extra='')=>`<input name="${name}" value="${esc(value)}" ${extra}>`;
const fArea=(name,value='',extra='')=>`<textarea name="${name}" ${extra}>${esc(value)}</textarea>`;
function selectX(name,values,current,extra=''){return `<select name="${name}" ${extra}>${values.map(v=>opt(v,v,current)).join('')}</select>`;}
const storeInput=(item={})=>field('store_id','Toko',`<select name="store_id" required>${scopeStores().map(s=>opt(s.id,s.name,item.store_id||state.profile?.store_id||scopeStores()[0]?.id)).join('')}</select>`);
function photoWidget(name,old=''){return `<div class="photo-input"><input type="file" name="${name}" accept="image/jpeg,image/png,image/webp" capture="environment"><small>Foto asal maks. 30 MB • Otomatis WebP, diperkecil maks. 1.600 px. ${old?'Bukti lama tetap tersimpan bila tidak memilih foto.':''}</small>${old?`<button type="button" class="btn small" data-photo="${esc(old)}">Lihat foto tersimpan</button>`:''}</div>`;}
function visitPointMarkup(p,i){const code=esc(p.point_code),s=p.section||'General';return `<div class="visit-point" data-point-code="${code}"><div class="point-num">${String(i+1).padStart(2,'0')}</div><div class="point-main"><b>${esc(p.item_title)}</b><small>${esc(s)} · ${esc(p.description||'')}</small><div class="point-actions"><select name="point_result_${code}" aria-label="Status ${code}"><option value="Belum">Belum diperiksa</option><option value="Sesuai">✓ Sesuai</option><option value="Tidak Sesuai">✕ Tidak sesuai</option><option value="N/A">Tidak berlaku</option></select><input name="point_note_${code}" placeholder="Catatan point (opsional)"></div>${photoWidget(`point_photo_${code}`)}</div></div>`;}
function visitIssueRow(index){const codes=state.data.visit_templates.filter(p=>p.active).sort((a,b)=>a.sort_order-b.sort_order);return `<div class="visit-issue-row" data-visit-issue><div class="issue-line-header"><b>Issue #${index}</b><button type="button" class="btn small danger" data-action="remove-visit-issue">Hapus</button></div><div class="form-grid"><div class="field"><label>Point terkait</label><select data-issue-field="point_code"><option value="">Umum / tanpa point</option>${codes.map(p=>`<option value="${esc(p.point_code)}">${esc(p.point_code)} · ${esc(p.item_title)}</option>`).join('')}</select></div><div class="field"><label>Prioritas</label><select data-issue-field="priority">${PRIORITIES.map(x=>opt(x,x,'Sedang')).join('')}</select></div>${field('title','Temuan',`<input data-issue-field="title" placeholder="Jelaskan ketidaksesuaian">`,true)}${field('action_plan','Action Plan',`<input data-issue-field="action_plan" placeholder="Tindakan korektif spesifik">`,true)}${field('pic_name','PIC',`<input data-issue-field="pic_name" placeholder="Penanggung jawab">`)}${field('due_date','Due Date',`<input data-issue-field="due_date" type="date">`)}</div></div>`;}
function modalContent(){const kind=state.modal,existing=state.editing||{},input=existing;let title='',html='';
 if(kind==='issue'){
 title=existing.id?'Update Issue / Action Plan':'Input Issue Baru';
 html=storeInput(input)+field('priority','Prioritas',selectX('priority',PRIORITIES,input.priority||'Sedang'))+field('title','Masalah / Temuan',fArea('title',input.title,'required minlength="5"'),true)+field('category','Kategori',fInput('category',input.category||'Operasional','required'))+field('origin','Asal Issue',selectX('origin',['briefing','visit','other'],input.origin||'briefing'))+field('root_cause','Akar Penyebab',fArea('root_cause',input.root_cause||''),true)+field('action_plan','Solusi / Action Plan',fArea('action_plan',input.action_plan||'','required'),true)+field('pic_name','PIC',fInput('pic_name',input.pic_name||'','required'))+field('due_date','Due Date',`<input name="due_date" type="date" value="${esc(input.due_date||'')}" required>`)+field('status','Status',selectX('status',STATUSES,input.status||'Open'))+field('progress','Progress (%)',`<input name="progress" type="number" min="0" max="100" value="${Number(input.progress)||0}" required>`)+field('note','Catatan Follow-up',fArea('note',input.note||''),true)+field('photo','Foto bukti',photoWidget('photo',input.photo_path),true);
 if(existing.id&&existing.status==='Selesai'&&!existing.verified_at&&mgr())html+=`<div class="form-full approval"><b>Validasi SPV</b><p>Verifikasi penyelesaian berdasarkan bukti.</p><input name="validation_notes" placeholder="Catatan validasi (opsional)"><button class="btn primary" type="button" data-verify-issue="${esc(existing.id)}">✔ Validasi selesai</button></div>`;
 if(existing.verified_at)html+=`<div class="form-full notice">✔ Tervalidasi pada ${esc(existing.verified_at.slice(0,16))}. Perubahan setelah validasi hanya oleh SPV/Master.</div>`;
 }else if(kind==='briefing'){
 title='Briefing Harian Store';html=storeInput()+field('briefing_date','Tanggal (WITA)',`<input name="briefing_date" type="date" value="${state.date}" required>`)+field('shift','Shift',selectX('shift',['Pagi','Siang','Sore','Malam'],'Pagi'))+field('leader','Pemimpin',fInput('leader',state.profile?.display_name||'','required'))+field('participants','Jumlah Peserta',`<input name="participants" type="number" min="0" value="0">`)+field('no_findings','Hasil Briefing',`<select name="no_findings" id="briefingFinding"><option value="true">NIHIL — tidak ada masalah</option><option value="false">Ada masalah — wajib dicatat</option></select>`,true)+field('notes','Ringkasan',fArea('notes',''),true)+`<div class="form-full hidden" id="briefingIssueGroup"><div class="group-label">List masalah briefing <button type="button" class="btn small" data-action="add-briefing-issue">＋ Tambah temuan</button></div><div id="briefingIssueRows">${briefingIssueRow(1)}</div></div>`;
 }else if(kind==='schedule'){
 title=existing.id?'Edit Jadwal Visit':'Buat Jadwal Visit';html=storeInput(input)+field('visit_date','Tanggal',`<input name="visit_date" type="date" value="${esc(input.visit_date||state.date)}" required>`)+field('start_time','Jam Mulai (WITA)',`<input name="start_time" type="time" value="${esc(input.start_time?.slice(0,5)||'09:00')}" required>`)+field('end_time','Jam Selesai (WITA)',`<input name="end_time" type="time" value="${esc(input.end_time?.slice(0,5)||'11:00')}" required>`)+field('pic_name','PIC / SPV',fInput('pic_name',input.pic_name||state.profile?.display_name||'','required'))+field('status','Status',selectX('status',['Rencana','Selesai','Batal'],input.status||'Rencana'))+field('agenda','Agenda dan Target Visit',fArea('agenda',input.agenda||'','required'),true)+field('notes','Catatan Kegiatan',fArea('notes',input.notes||''),true);
 }else if(kind==='visit'){
 title='Visiting Check Point — Audit Store';const pts=state.data.visit_templates.filter(x=>x.active).sort((a,b)=>a.sort_order-b.sort_order);
 html=storeInput()+field('visit_date','Tanggal Visit',`<input name="visit_date" type="date" value="${state.date}" required>`)+field('evaluator_name','Evaluator / SPV',fInput('evaluator_name',state.profile?.display_name||'','required'))+field('leader_name','Leader In Charge',fInput('leader_name','','required'))+field('visit_type','Jenis Visit',selectX('visit_type',['Rutin','Audit','Follow-up','Insidental'],'Rutin'))+field('notes','Ringkasan Visit',fArea('notes',''),true)+`<div class="form-full group-label">Checkpoint (${pts.length}) · Pilih status dan foto setiap point</div><div class="form-full visit-points">${pts.map(visitPointMarkup).join('')}</div><div class="form-full"><div class="group-label">Issue hasil visit <span class="mild">(maks. 150; setiap point Tidak Sesuai wajib memiliki issue)</span><button type="button" class="btn small" data-action="add-visit-issue">＋ Tambah issue</button></div><div id="visitIssueRows">${visitIssueRow(1)}</div></div>`;
 }else if(kind==='checklist'){
 title='Update Assignment Checklist';html=storeInput(input)+field('check_date','Tanggal',`<input name="check_date" type="date" value="${esc(input.check_date||state.date)}" required>`)+field('title','Tugas',fInput('title',input.title||'','readonly'))+field('status','Status',selectX('status',['Belum','Selesai'],input.status||'Belum'))+field('note','Catatan',fArea('note',input.note||''),true)+field('photo','Bukti Foto',photoWidget('photo',input.photo_path),true);
 }else if(kind==='dso'){
 title=`${esc(state.dsoForm)} Report`;const pts=state.data.dso_points.filter(x=>x.active&&x.form_code===state.dsoForm).sort((a,b)=>a.sort_order-b.sort_order);
 html=storeInput(input)+field('report_date','Tanggal',`<input name="report_date" type="date" value="${esc(input.report_date||state.date)}" required>`)+field('notes','Keterangan',fArea('notes',input.notes||''),true)+`<div class="form-full group-label">Foto checkpoint ${esc(state.dsoForm)}</div>`+pts.map(x=>`<div class="form-full dso-photo-row"><b>${esc(x.label)}${x.required?' *':''}</b><small>${esc(x.description)}</small>${photoWidget('dso_photo_'+x.point_code,input.answers?.[x.point_code]||'')}</div>`).join('')+`<div class="form-full notice">Form hanya dianggap terkirim setelah semua foto wajib selesai diunggah.</div>`;
 if(existing.id&&mgr()&&existing.status==='Submitted')html+=`<div class="form-full approval"><b>Validasi SPV/Master</b><input id="dsoValidationNote" placeholder="Keterangan validasi / alasan reject"><button type="button" class="btn primary" data-dso-validate="${esc(existing.id)}" data-validation="Approved">✔ Approve</button> <button type="button" class="btn danger" data-dso-validate="${esc(existing.id)}" data-validation="Rejected">✕ Reject</button></div>`;
 }else if(kind==='assignment'){
 title=existing.id?'Edit Assignment':'Assignment Baru';html=storeInput(input)+field('title','Judul Tugas',fInput('title',input.title||'','required'))+field('pic_name','PIC',fInput('pic_name',input.pic_name||'','required'))+field('due_date','Due Date',`<input name="due_date" type="date" value="${esc(input.due_date||state.date)}" required>`)+field('priority','Prioritas',selectX('priority',PRIORITIES,input.priority||'Sedang'))+field('status','Status',selectX('status',STATUSES,input.status||'Open'))+field('progress','Progress',`<input name="progress" type="number" min="0" max="100" value="${input.progress||0}">`)+field('description','Deskripsi',fArea('description',input.description||''),true);
 }else if(kind==='check-template'){
 title='Template Assignment Checklist';html=field('store_id','Untuk toko',`<select name="store_id">${opt('','Semua toko','')}${scopeStores().map(s=>opt(s.id,s.name,'')).join('')}</select>`)+field('title','Nama Assignment',fInput('title','','required'))+field('description','Instruksi',fArea('description',''),true)+field('category','Kategori',fInput('category','Operasional'))+field('frequency','Frekuensi',selectX('frequency',['Harian','Mingguan','Bulanan'],'Harian'))+field('priority','Prioritas',selectX('priority',PRIORITIES,'Sedang'));
 }else if(kind==='visit-template'){
 title='Tambah Point Visit';html=field('point_code','Kode Point',fInput('point_code','','required'))+field('section','Seksi',selectX('section',['Finance','Asset & GA','Merchandise','Human Resources','Warehouse','Operasional'],'Operasional'))+field('item_title','Judul Point',fInput('item_title','','required'))+field('sort_order','Urutan',`<input name="sort_order" type="number" min="0" value="${state.data.visit_templates.length+1}">`)+field('description','Deskripsi',fArea('description',''),true);
 }else if(kind==='dso-template'){
 title='Tambah Point DSO';html=field('form_code','Jenis Form',selectX('form_code',['OPENING','DURING','CLOSING','LAMPU'],'OPENING'))+field('point_code','Kode Point',fInput('point_code','','required'))+field('label','Nama Foto',fInput('label','','required'))+field('description','Instruksi',fArea('description',''),true)+field('sort_order','Urutan',`<input name="sort_order" type="number" value="10">`);
 }else if(kind==='visit-detail'){
  title='Detail Visit';const v=input;const points=state.data.visit_points.filter(x=>x.visit_id===v.id),list=issues().filter(x=>x.visit_id===v.id);
  html=`<div class="form-full notice">${showStore(v.store_id)} · ${prettyDate(v.visit_date)} · ${esc(v.evaluator_name)} · Skor ${v.score==null?'—':v.score+'%'}</div><div class="form-full group-label">Checkpoint</div><div class="form-full">${points.map(p=>`<div class="checkpoint-item"><b>${esc(p.point_code)} · ${esc(p.item_title)}</b>${badge(p.result,p.result==='Tidak Sesuai'?'overdue':'done')}${p.photo_path?`<button type="button" class="btn small" data-photo="${esc(p.photo_path)}">Foto</button>`:''}<small>${esc(p.notes||'')}</small></div>`).join('')||empty()}</div><div class="form-full group-label">Issue (${list.length})</div><div class="form-full">${list.map(x=>`<div class="checkpoint-item"><b>${esc(x.title)}</b><small>${esc(x.pic_name||'—')} · ${prettyDate(x.due_date)}</small>${status(x.status)}<button type="button" class="btn small" data-edit-issue="${x.id}">Buka issue</button></div>`).join('')||empty('Visit tidak memiliki issue.')}</div>`;
 }
 return `<div class="modal-backdrop" data-action="modal-backdrop"><form id="modalForm" class="modal ${kind==='visit'||kind==='visit-detail'?'modal-wide':''}" data-form="${kind}" novalidate><div class="modal-head"><div><span class="eyebrow">OPERASIONAL / INPUT & VALIDASI</span><h3>${title}</h3></div><button type="button" class="circle-btn" data-action="modal-close" title="Tutup">×</button></div><div class="modal-body form-grid">${html}</div><div class="modal-footer"><button type="button" class="btn" data-action="modal-close">Tutup</button>${kind!=='visit-detail'?`<button type="submit" class="btn primary" ${state.busy?'disabled':''}>${state.busy?'Menyimpan…':'Simpan ke Supabase'}</button>`:''}</div></form></div>`;
}
function briefingIssueRow(idx){return `<div class="briefing-issue-row" data-briefing-issue><div class="issue-line-header"><b>Temuan ${idx}</b><button type="button" data-action="remove-briefing-issue" class="btn small danger">Hapus</button></div><div class="form-grid">${field('title','Masalah',`<input data-brief-field="title" placeholder="Temuan yang perlu ditindaklanjuti">`,true)}${field('action_plan','Solusi / Action',`<input data-brief-field="action_plan" placeholder="Tindakan spesifik">`,true)}${field('pic_name','PIC',`<input data-brief-field="pic_name" placeholder="Penanggung jawab">`)}${field('due_date','Due Date',`<input type="date" data-brief-field="due_date">`)}${field('priority','Prioritas',`<select data-brief-field="priority">${PRIORITIES.map(p=>opt(p,p,'Sedang')).join('')}</select>`)}</div></div>`;}
// Evidence is rendered inside HTML from a short-lived signed URL, not embedded as base64.
function showEvidenceLightbox(url,path){
 document.querySelector('.evidence-lightbox')?.remove();
 const overlay=document.createElement('div');overlay.className='evidence-lightbox';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','Pratinjau bukti foto');
 const close=document.createElement('button');close.className='evidence-close';close.type='button';close.textContent='×';close.setAttribute('aria-label','Tutup foto');
 const img=document.createElement('img');img.src=url;img.alt='Foto bukti operasional';img.decoding='async';
 const label=document.createElement('small');label.textContent=path.split('/').pop();
 const frame=document.createElement('div');frame.className='evidence-frame';frame.append(close,img,label);overlay.append(frame);document.body.append(overlay);
 const release=()=>{document.removeEventListener('keydown',escKey);overlay.remove();};
 const escKey=e=>{if(e.key==='Escape')release();};
 close.addEventListener('click',release);overlay.addEventListener('click',e=>{if(e.target===overlay)release();});document.addEventListener('keydown',escKey);
 close.focus();
}
function render(){
 if(!state.profile){$('app').innerHTML=`<div class="login-page"><div class="login-card"><div class="brand-mark">T</div><h1>Assignment Control Center</h1><p>PT Tigalapan Sukses Indonesia · 12 Store</p>${!isConfigured?`<div class="notice">Konfigurasi belum lengkap. Set VITE_SUPABASE_URL dan VITE_SUPABASE_PUBLISHABLE_KEY di hosting, lalu redeploy.</div>`:`<form id="loginForm" class="login-form"><label>Email</label><input type="email" name="email" autocomplete="username" required><label>Password</label><input type="password" name="password" autocomplete="current-password" required minlength="8"><button class="btn primary" type="submit">Masuk dengan Supabase</button></form>`}${state.error?`<p class="text-red">${esc(state.error)}</p>`:''}<small>${isDemo?'DATA SIMULASI · bukan lingkungan produksi':'Supabase Auth + RLS · WITA'}</small></div></div>`;return;}
 const n=NAV.find(x=>x[0]===state.page)?.[1]||'Overview',profile=state.profile;
 let main='';if(!state.data)main=`<div class="empty">Memuat data Supabase…</div>`;
 else switch(state.page){case'overview':main=overview();break;case'compliance':main=pageCompliance();break;case'issues':main=pageIssues();break;case'pending':main=pageIssues(true);break;case'checklist':main=pageChecklist();break;case'dso':main=pageDso();break;case'schedule':main=pageSchedule();break;case'visits':main=pageVisits();break;case'scorecard':main=pageScore();break;case'assignments':main=pageAssignments();break;case'settings':main=pageSettings();break;case'maintenance':main=pageMaintenance();break;default:main=overview();}
 $('app').innerHTML=`<div class="mobile-overlay ${state.sidebar?'on':''}" data-action="sidebar-close"></div><div class="app"><aside class="sidebar ${state.sidebar?'open':''}"><div class="brand"><div class="brand-logo">T</div><div class="brand-name">TIGALAPAN <small>CONTROL CENTER</small></div></div><div class="nav-label">WORKSPACE</div><nav class="nav">${NAV.filter(x=>!['settings','maintenance'].includes(x[0])||master()).map(x=>`<button data-page="${x[0]}" class="${state.page===x[0]?'active':''}"><span class="glyph">${ICON[x[0]]||'◦'}</span>${x[1]}${x[0]==='pending'&&pending().length?`<span class="nav-badge">${pending().length}</span>`:''}</button>`).join('')}</nav><div class="side-footer"><div class="side-panel"><b>${esc(profile.display_name||profile.role)}</b><p>${esc(profile.role.toUpperCase())} · ${scopeStores().length} toko di akses</p><div class="mode-indicator"><i class="dot ${isDemo?'demo-dot':''}"></i>${isDemo?'DATA SIMULASI':'SUPABASE ONLINE'}</div><button class="btn small" data-action="logout" style="margin-top:10px">Keluar</button></div></div></aside><div class="viewport"><header class="topbar"><div class="top-left"><button class="menu-mobile" data-action="sidebar-toggle">☰</button><div><span class="crumb">Commercial / Operation</span><h1>${esc(n)}</h1></div></div><div class="top-right"><span class="time-label">${esc(new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Makassar',dateStyle:'full'}).format(new Date()))} · WITA</span><button class="circle-btn" data-action="reload" title="Refresh">↻</button><span class="avatar">${esc(profile.display_name?.slice(0,2).toUpperCase()||'TS')}</span></div></header><main class="page">${main}</main></div></div>${state.modal?modalContent():''}`;
}

function fieldRows(root,attr){return [...root.querySelectorAll(`[${attr}]`)].map(el=>Object.fromEntries([...el.querySelectorAll('[data-issue-field],[data-brief-field]')].map(x=>[x.dataset.issueField||x.dataset.briefField,x.value?.trim()||''])));}
function visitIssuesFrom(form){return fieldRows(form,'data-visit-issue').filter(i=>i.title).map(i=>({...i,category:'Operasional'}));}
function briefingIssuesFrom(form){return fieldRows(form,'data-briefing-issue').filter(i=>i.title).map(i=>({...i,category:'Operasional'}));}
function CSV(rows,file){if(!rows.length){toast('Belum ada data untuk diekspor.',true);return;}
 const cols=[...new Set(rows.flatMap(x=>Object.keys(x)))].filter(k=>!['password','pin','access_token','refresh_token','secret_key'].includes(k.toLowerCase()));const cell=x=>{let s=typeof x==='object'&&x!==null?JSON.stringify(x):String(x??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};
 const content='\ufeff'+[cols.join(','),...rows.map(r=>cols.map(k=>cell(r[k])).join(','))].join('\r\n');const blob=new Blob([content],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=file;link.click();setTimeout(()=>URL.revokeObjectURL(url),5000);
}
async function exportCurrent(){const dbMap={issues:'issues',pending:'issues',checklist:'checklists',dso:'dso',schedule:'schedules',visits:'visits',assignments:'assignments',compliance:'briefings',settings:'visit_templates'};if(dbMap[state.page]){await exportDatasetNow(dbMap[state.page],{store:state.store,origin:state.page==='pending'?'visit':'',from:['checklist','dso','compliance'].includes(state.page)?state.date:'',to:['checklist','dso','compliance'].includes(state.page)?state.date:''});return;}let rows=[];switch(state.page){case'overview':case'issues':case'pending':rows=issues().filter(x=>state.page!=='pending'||x.origin==='visit').filter(x=>(state.status==='all'||x.status===state.status)&&(!state.search||[x.title,x.pic_name,storeName(x.store_id)].join(' ').toLowerCase().includes(state.search.toLowerCase())));break;
 case'compliance':rows=scopeStores().map(s=>({tanggal:state.date,toko:s.name,status:briefingStores().has(s.id)?'Sudah Update':'Belum Update',total_sesi:dayBriefings().filter(b=>b.store_id===s.id).length}));break;
 case'checklist':rows=scoped(state.data.checklists).filter(r=>r.check_date===state.date);break;
 case'dso':rows=scoped(state.data.dso).filter(r=>r.report_date===state.date);break;
 case'schedule':rows=scoped(state.data.schedules);break;
 case'visits':rows=scoped(state.data.visits);break;
 case'assignments':rows=scoped(state.data.assignments);break;
 case'scorecard':rows=scopeStores().map(s=>({toko:s.name,total_issue:issues().filter(i=>i.store_id===s.id).length,open:issues().filter(i=>i.store_id===s.id&&isOpen(i)).length}));break;
 case'settings':rows=state.data.visit_templates;break;default:rows=[];}
 CSV(rows,`tigalapan_${state.page}_${state.date}.csv`);
}
async function refresh(message=false){try{state.data=await loadAll(state.profile);render();if(message)toast('Data berhasil dimuat ulang.');}catch(e){toast('Gagal membaca Supabase: '+e.message,true);}}
function go(page){state.page=page;state.sidebar=false;state.search='';state.status='all';state.subTab='ringkasan';state.modal=null;state.editing=null;render();window.scrollTo({top:0,behavior:'instant'});if(page==='maintenance')loadMaintenance().catch(e=>toast(e.message,true));}
function openModal(kind,item=null){state.modal=kind;state.editing=item;state.busy=false;render();}
async function readFiles(form,storeId,names,module){const output={};for(const name of names){const el=form.querySelector(`input[name="${name}"]`);if(el?.files?.[0])output[name]=await uploadEvidence(storeId,module,el.files[0]);}return output;}
async function doSave(form){if(state.busy)return;
 if(!form.reportValidity()){toast('Lengkapi field wajib yang ditandai.',true);return;}
 const kind=form.dataset.form;if(kind==='visit-detail')return;
 const raw=Object.fromEntries(new FormData(form).entries()),d=Object.fromEntries(Object.entries(raw).filter(([k,v])=>!(v instanceof File)));const edit=state.editing||{};
 state.busy=true;const button=form.querySelector('[type="submit"]');button&&(button.disabled=true,button.textContent='Menyimpan…');
 try{
  if(kind==='issue'){
   const file=await readFiles(form,d.store_id,['photo'],'issue');
   const item={id:edit.id,store_id:d.store_id,title:d.title,category:d.category,origin:d.origin||'other',root_cause:d.root_cause||null,action_plan:d.action_plan,pic_name:d.pic_name,due_date:d.due_date||null,priority:d.priority,status:d.status,progress:Number(d.progress)||0,note:d.note||null,photo_path:file.photo||edit.photo_path||null};
   await saveIssue(item);
  }else if(kind==='briefing'){
   const list=d.no_findings==='true'?[]:briefingIssuesFrom(form);
   if(d.no_findings==='false'&&!list.length)throw new Error('Isi minimal satu masalah atau pilih NIHIL.');
   for(const item of list)if(!item.action_plan||!item.pic_name||!item.due_date)throw new Error('Temuan briefing wajib mempunyai action, PIC dan due date.');
   await submitBriefingBundle({...d,participants:Number(d.participants)||0,no_findings:d.no_findings==='true'},list);
  }else if(kind==='schedule'){
   if(d.end_time<=d.start_time)throw new Error('Jam selesai harus lebih besar dari jam mulai.');
   await saveSchedule({...d,...(edit.id?{id:edit.id}:{})});
  }else if(kind==='visit'){
   if(!mgr())throw new Error('Hanya SPV/Master dapat submit visit.');
   const points=state.data.visit_templates.filter(x=>x.active).map(p=>({point_code:p.point_code,item_title:p.item_title,section:p.section,result:form.querySelector(`[name="point_result_${p.point_code}"]`)?.value||'Belum',notes:form.querySelector(`[name="point_note_${p.point_code}"]`)?.value||''}));
   const issueList=visitIssuesFrom(form);
   for(const issue of issueList)if(!issue.pic_name||!issue.due_date||!issue.action_plan)throw new Error('Setiap issue visit wajib punya action plan, PIC dan due date.');
   const missing=points.filter(p=>p.result==='Tidak Sesuai'&&!issueList.some(i=>i.point_code===p.point_code));
   if(missing.length)throw new Error('Point '+missing.map(x=>x.point_code).join(', ')+' Tidak Sesuai tetapi belum punya issue terkait.');
   if(points.every(x=>x.result==='Belum'))throw new Error('Nilai minimal satu checkpoint sebelum menyimpan visit.');
   for(const p of points){const name='point_photo_'+p.point_code;const files=await readFiles(form,d.store_id,[name],'visit');p.photo_path=files[name]||null;}
   await submitVisitBundle({store_id:d.store_id,visit_date:d.visit_date,evaluator_name:d.evaluator_name,leader_name:d.leader_name,visit_type:d.visit_type,notes:d.notes},points,issueList);
  }else if(kind==='checklist'){
   const file=await readFiles(form,d.store_id,['photo'],'checklist');
   await saveChecklist({id:edit.id,store_id:d.store_id,check_date:d.check_date,template_id:edit.template_id,title:d.title,status:d.status,note:d.note||'',photo_path:file.photo||edit.photo_path||null});
  }else if(kind==='dso'){
   if(edit.status==='Approved'&&!mgr())throw new Error('Laporan telah Approved; tidak bisa diubah.');
   const formCode=state.dsoForm,points=state.data.dso_points.filter(x=>x.active&&x.form_code===formCode),answers={...(edit.answers||{})};
   for(const p of points){const name='dso_photo_'+p.point_code;const files=await readFiles(form,d.store_id,[name],'dso');if(files[name])answers[p.point_code]=files[name];if(p.required&&!answers[p.point_code])throw new Error(`Foto wajib belum diisi: ${p.label}`);}
   await saveDso({store_id:d.store_id,report_date:d.report_date,form_code:formCode,notes:d.notes||'',status:'Submitted',answers,validated_at:null,validated_by:null,validation_notes:null});
  }else if(kind==='assignment'){
   await saveAssignment({...d,...(edit.id?{id:edit.id}:{}),progress:Number(d.progress)||0});
  }else if(['check-template','visit-template','dso-template'].includes(kind)){
   if(!master())throw new Error('Hanya Master dapat mengubah template.');
   const table=kind==='check-template'?'checklist_templates':kind==='visit-template'?'visit_templates':'dso_form_points';
   const item={...d,sort_order:d.sort_order?Number(d.sort_order):0};if(item.store_id==='')item.store_id=null;
   if(kind==='check-template'){delete item.sort_order;item.active=true;}
   if(kind==='visit-template')item.active=true;
   if(kind==='dso-template'){item.required=true;item.require_photo=true;item.active=true;}
   await saveTemplate(table,item);
  }else throw new Error('Form tidak dikenal.');
  state.busy=false;state.modal=null;state.editing=null;await refresh();toast('Tersimpan ke database Supabase.');
 }catch(e){state.busy=false;if(button){button.disabled=false;button.textContent='Simpan ke Supabase';}toast(e.message||String(e),true);}
}
async function handleAction(ev){const t=ev.target.closest('button,[data-page],[data-photo],[data-check-entry],[data-check-detail]');if(!t)return;
 if(t.dataset.page){go(t.dataset.page);return;}
 if(t.dataset.subtab){state.subTab=t.dataset.subtab;render();return;}
 if(t.dataset.editIssue){const item=state.data.issues.find(i=>i.id===t.dataset.editIssue);if(item)openModal('issue',item);return;}
 if(t.dataset.editSchedule){const item=state.data.schedules.find(i=>i.id===t.dataset.editSchedule);if(item)openModal('schedule',item);return;}
 if(t.dataset.editAssignment){const item=state.data.assignments.find(i=>i.id===t.dataset.editAssignment);if(item)openModal('assignment',item);return;}
 if(t.dataset.detailVisit){const item=state.data.visits.find(i=>i.id===t.dataset.detailVisit);if(item)openModal('visit-detail',item);return;}
 if(t.dataset.dsoStore){state.dsoForm=t.dataset.dsoForm;const item=state.data.dso.find(x=>x.store_id===t.dataset.dsoStore&&x.form_code===t.dataset.dsoForm&&x.report_date===state.date)||{store_id:t.dataset.dsoStore,report_date:state.date};openModal('dso',item);return;}
 if(t.dataset.photo){try{const url=await evidenceUrl(t.dataset.photo);if(url){showEvidenceLightbox(url,t.dataset.photo);}else toast('Foto preview hanya tersedia dengan Supabase aktif.');}catch(e){toast(e.message,true);}return;}
 if(t.dataset.checkDetail!==undefined){const entry=state.data.checklists.find(x=>x.id===t.dataset.checkDetail),tpl=state.data.checklist_templates.find(x=>x.id===t.dataset.checkTemplate);openModal('checklist',entry||{store_id:t.dataset.checkStore,check_date:state.date,template_id:tpl.id,title:tpl.title,status:'Belum'});return;}
 if(t.dataset.checkEntry!==undefined){const entry=state.data.checklists.find(x=>x.id===t.dataset.checkEntry),tpl=state.data.checklist_templates.find(x=>x.id===t.dataset.checkTemplate);if(entry?.validated_at&&!mgr())return toast('Sudah divalidasi SPV.',true);
  try{await saveChecklist({id:entry?.id,store_id:t.dataset.checkStore,check_date:state.date,template_id:tpl.id,title:tpl.title,status:entry?.status==='Selesai'?'Belum':'Selesai',note:entry?.note||'',photo_path:entry?.photo_path||null});await refresh();}catch(e){toast(e.message,true);}return;
 }
 if(t.dataset.checkValidate){try{await validateChecklist(t.dataset.checkValidate,true);await refresh();toast('Checklist divalidasi.');}catch(e){toast(e.message,true);}return;}
 if(t.dataset.verifyIssue){try{if(!mgr())throw new Error('Hanya SPV/Master.');const note=$('modalForm')?.querySelector('[name=validation_notes]')?.value||'';await verifyIssue(t.dataset.verifyIssue,note);state.modal=null;await refresh();toast('Issue telah divalidasi.');}catch(e){toast(e.message,true);}return;}
 if(t.dataset.dsoValidate){try{if(!mgr())throw new Error('Hanya SPV/Master.');const note=$('dsoValidationNote')?.value||'';if(t.dataset.validation==='Rejected'&&!note.trim())throw new Error('Alasan penolakan wajib diisi.');await validateDso(t.dataset.dsoValidate,t.dataset.validation,note);state.modal=null;await refresh();toast('Validasi laporan tersimpan.');}catch(e){toast(e.message,true);}return;}
 if(t.dataset.scheduleView){state.scheduleView=t.dataset.scheduleView;render();return;}
 const a=t.dataset.action;
 if(a==='modal-close'||a==='modal-backdrop'&&ev.target===t){state.modal=null;state.editing=null;render();return;}
 if(a==='sidebar-close'){state.sidebar=false;render();return;}
 if(a==='sidebar-toggle'){state.sidebar=!state.sidebar;render();return;}
 if(a==='reload'){await refresh(true);return;}
 if(a==='apply'||a==='apply-issues'){
  state.date=$('monitorDate')?.value||state.date;state.store=$('storeFilter')?.value||state.store;
  state.brand=$('brandFilter')?.value||state.brand;state.status=$('issueStatus')?.value||'all';state.search=$('issueSearch')?.value?.trim()||'';render();return;
 }
 if(a==='export'){await exportCurrent();return;}
 if(a==='reload-maintenance'){await loadMaintenance();return;}
 if(a==='preview-maintenance'){await previewMaintenance();return;}
 if(a==='archive-maintenance'){await archiveMaintenance();return;}
 if(a==='export-dataset'){await exportDatasetNow($('exportDataset')?.value,{store:$('exportStore')?.value||'all',from:$('exportFrom')?.value||'',to:$('exportTo')?.value||''});return;}
 if(a==='backup-all'){await backupAllDatasets();return;}
 if(a==='download-archive'){await downloadArchiveRecord(t.dataset.batch);return;}
 if(a==='purge-archive'){await purgeArchiveRecord(t.dataset.batch);return;}
 if(a==='open-issue'){openModal('issue');return;}if(a==='open-briefing'){openModal('briefing');return;}
 if(a==='open-schedule'){openModal('schedule');return;}if(a==='open-visit'){openModal('visit');return;}
 if(a==='open-assignment'){openModal('assignment');return;}if(a==='open-check-template'){openModal('check-template');return;}
 if(a==='open-visit-template'){openModal('visit-template');return;}if(a==='open-dso-template'){openModal('dso-template');return;}
 if(a==='add-visit-issue'){const list=$('visitIssueRows');if(list.querySelectorAll('[data-visit-issue]').length>=150)return toast('Maksimal 150 issue per visit.',true);list.insertAdjacentHTML('beforeend',visitIssueRow(list.children.length+1));return;}
 if(a==='remove-visit-issue'){t.closest('[data-visit-issue]')?.remove();return;}
 if(a==='add-briefing-issue'){const list=$('briefingIssueRows');if(list.children.length>=50)return toast('Maksimal 50 issue per briefing.',true);list.insertAdjacentHTML('beforeend',briefingIssueRow(list.children.length+1));return;}
 if(a==='remove-briefing-issue'){t.closest('[data-briefing-issue]')?.remove();return;}
 if(a==='logout'){await logout();state.profile=null;state.data=null;render();return;}
}
async function init(){try{const {profile}=await start();state.profile=profile;state.error=null;if(profile)state.data=await loadAll(profile);render();}catch(e){state.error=e.message||String(e);state.profile=null;render();}}
document.addEventListener('click',e=>{handleAction(e).catch(x=>toast(x.message||String(x),true));});
document.addEventListener('change',e=>{if(e.target.id==='briefingFinding')$('briefingIssueGroup')?.classList.toggle('hidden',e.target.value==='true');});
document.addEventListener('submit',async e=>{
 if(e.target.id==='modalForm'){e.preventDefault();await doSave(e.target);}
 else if(e.target.id==='loginForm'){e.preventDefault();const v=Object.fromEntries(new FormData(e.target).entries());try{state.profile=await login(v.email,v.password);state.data=await loadAll(state.profile);state.error=null;render();}catch(x){state.error=x.message||String(x);render();}}
});
init();
